// Package worktreedir owns access to the files of the working tree itself.
//
// It is the third of Entire's three anchors, alongside entiredir (.entire) and
// gitdir (the git common dir), and the loosest of them: a root here contains
// operations to the repository rather than to a directory Entire owns. That is
// still worth having, because the paths that reach these reads and writes are
// not Entire's own:
//
//   - Checkpoint writes read working files named by `git status` output, on the
//     hook path, to turn them into blobs.
//   - Rewind writes working files named by git TREE ENTRIES out of a checkpoint,
//     which may have been fetched from a remote. Its restore half already opened
//     a root for exactly this reason; the reads beside it did not.
//   - Diff-stat and gather read working files named from status output too.
//
// A root makes "cannot leave the repository" a property of the handle rather
// than of each caller remembering to validate. It is not a substitute for the
// tree-path validation those callers do — normalizeRepoRelativeTreePath still
// rejects names that are not repo-relative before they are used as git paths —
// it is the layer underneath it.
package worktreedir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Open returns the shared *os.Root over the current worktree root. The returned
// root is owned by the registry and shared with every other caller; do not close
// it.
func Open(ctx context.Context) (*os.Root, error) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve worktree root: %w", err)
	}
	return OpenAt(root)
}

// OpenAt is Open for an explicit worktree root, for callers that resolved one
// already or that act on a worktree other than the current directory.
func OpenAt(worktreeRoot string) (*os.Root, error) {
	if worktreeRoot == "" {
		return nil, errors.New("worktreedir: worktree root is required")
	}
	abs, err := filepath.Abs(worktreeRoot)
	if err != nil {
		return nil, fmt.Errorf("resolve %s: %w", worktreeRoot, err)
	}
	return osroot.Shared(abs) //nolint:wrapcheck // Shared names the directory and returns a missing one unwrapped
}

// Name converts a path inside the worktree to a name relative to its root,
// accepting either an absolute path or one already relative to the root.
//
// Git hands out slash-separated repo-relative paths and Entire assembles
// absolute ones from them; this is the single conversion back, so callers stop
// joining a root path onto a git path and reading the result.
func Name(worktreeRoot, p string) (string, error) {
	if !filepath.IsAbs(p) {
		cleaned := filepath.ToSlash(filepath.Clean(filepath.FromSlash(p)))
		if cleaned == "." || paths.IsRelativeTraversal(cleaned) {
			return "", fmt.Errorf("%q does not name a file in the worktree", p)
		}
		return cleaned, nil
	}
	base, err := filepath.Abs(worktreeRoot)
	if err != nil {
		return "", fmt.Errorf("resolve %s: %w", worktreeRoot, err)
	}
	rel, err := filepath.Rel(base, p)
	if err != nil || rel == "." || paths.IsRelativeTraversal(rel) {
		return "", fmt.Errorf("%q is not inside %q", p, worktreeRoot)
	}
	return filepath.ToSlash(rel), nil
}
=== GITDIR ===
// Package gitdir owns access to the git common directory — .git in an ordinary
// checkout, and the main repository's .git when running from a linked worktree.
//
// Entire keeps a lot of state there, deliberately: session state, advisory
// locks, the checkpoint push queue, the redaction prefix cache, investigation
// runs, review manifests, and the captured checkpoint-sync election all live in
// the common dir rather than under .entire, because they are per-clone and must
// not be committed or walked into a checkpoint tree. That makes this directory
// the same kind of trust surface .entire is, and it gets the same treatment: one
// *os.Root per common dir, opened once and shared, with every read and write
// resolved as a name inside it.
//
// Two properties come from that, and neither survives a call site reverting to
// os.ReadFile on a joined path:
//
//   - Containment. Names here are built from agent-supplied session IDs and
//     investigation run IDs. Several call sites carry hand-written comments
//     explaining that an unvalidated ID would be a path-traversal sink feeding
//     os.RemoveAll. A root makes that structural instead of a precondition each
//     caller has to keep honouring.
//   - One directory handle per clone. The resolver shells out to git; before
//     this package, strategy.GetGitCommonDir did so on *every* call with no
//     cache at all, on hook paths.
//
// Unlike .entire there is no create/no-create split: the common dir is the
// repository, so it always exists by the time anything here is called. What
// needs creating are Entire's own subdirectories inside it, via
// osroot.MkdirAllNoSymlink.
package gitdir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

var (
	// resolveMu guards the resolved-path cache, which is keyed by the working
	// directory the answer was derived in (see CommonDir).
	resolveMu     sync.RWMutex
	cachedDir     string
	cachedFromCwd string
)

// CommonDir returns the absolute path of the git common directory, caching the
// result per working directory.
//
// Absolute is the load-bearing word. `git rev-parse --git-common-dir` answers
// relative to the process's directory — from a subdirectory it returns
// "../../../.git" — and the two implementations this replaced passed that
// straight through, so every path built on it was only valid while the process
// stayed put. Resolving it once here means a stored lock path or queue path
// still names the same file later, and it is what lets Open hold a handle
// rather than re-resolving a string.
func CommonDir(ctx context.Context) (string, error) {
	cwd, err := os.Getwd() //nolint:forbidigo // cache key, and the base the git answer is relative to
	if err != nil {
		cwd = ""
	}

	resolveMu.RLock()
	if cachedDir != "" && cachedFromCwd == cwd {
		cached := cachedDir
		resolveMu.RUnlock()
		return cached, nil
	}
	resolveMu.RUnlock()

