func openFDs(t *testing.T) int {
	t.Helper()
	entries, err := os.ReadDir("/proc/self/fd")
	if err != nil {
		t.Skipf("no /proc: %v", err)
	}
	return len(entries)
}

func TestZZFDGrowthFromSessionStoreExists(t *testing.T) {
	base := t.TempDir()
	const candidates = 200
	for i := range candidates {
		d := filepath.Join(base, fmt.Sprintf("-Users-someone-project-%03d", i))
		if err := os.MkdirAll(d, 0o750); err != nil {
			t.Fatal(err)
		}
	}

	ag := &claudecode.ClaudeCodeAgent{}
	before := openFDs(t)
	for i := range candidates {
		d := filepath.Join(base, fmt.Sprintf("-Users-someone-project-%03d", i))
		store, err := agentpkg.OpenSessionStoreAt(ag, d)
		if err != nil {
			t.Fatal(err)
		}
		name, _, err := store.SessionFile("11111111-2222-3333-4444-555555555555")
		if err != nil {
			t.Fatal(err)
		}
		store.Exists(name) // the probe: file is absent in every candidate
	}
	after := openFDs(t)
	t.Logf("candidate dirs probed: %d", candidates)
	t.Logf("open fds before=%d after=%d  delta=%d", before, after, after-before)

	// For contrast, the pre-branch shape.
	before2 := openFDs(t)
	for i := range candidates {
		d := filepath.Join(base, fmt.Sprintf("-Users-someone-project-%03d", i))
		_, _ = os.Stat(filepath.Join(d, "11111111-2222-3333-4444-555555555555.jsonl"))
	}
	t.Logf("os.Stat equivalent delta=%d", openFDs(t)-before2)
}
